"""Sufficient perimeter proof from two ordered piecewise-linear graphs.

Includes the original terminal caps. Extending the shorter side at either end
by its actual cap produces two graphs over the same axial interval. The gap
between them is affine between the union of their knots. A strictly signed gap
there proves separation everywhere; coincident graph endpoints are permitted
only at the two extrema, where they represent the same cap endpoint.

This checks the actual polygon, not a resampled or smoothed approximation.
Nonmonotone or numerically unresolved inputs must use the exhaustive guard.
"""
from . import boundary_quad_bridge_nodes as bridge


def certificate(g,mesh,ny,nx,index,pos,axis,tolerance):
    axis=g.vector('NORMALIZE',g.xyz(g.component(axis,'X'),g.component(axis,'Y')))
    normal=g.right(axis)
    origin=g.sample(mesh,pos,0,'FLOAT_VECTOR')
    last=g.math('SUBTRACT',ny,1.)
    base=g.math('MULTIPLY',g.math('SUBTRACT',nx,1.),ny)

    def sample(side,at):
        vertex=g.math('ADD',base,at) if side else at
        point=g.vector('SUBTRACT',g.sample(mesh,pos,vertex,'FLOAT_VECTOR'),origin)
        return g.xyz(g.component(point,'X'),g.component(point,'Y'))

    def metric(point):return g.vector('DOT_PRODUCT',point,axis)
    endpoints=[(sample(side,0),sample(side,last)) for side in (0,1)]
    ordered=[];checks=[];queries=[];slopes=[]
    for side in (0,1):
        own_start,own_end=endpoints[side];other_start,other_end=endpoints[1-side]
        prepend=g.compare(metric(other_start),metric(own_start),'LESS_THAN')
        append=g.compare(metric(other_end),metric(own_end),'GREATER_THAN')
        line=g.node('GeometryNodeMeshLine','Original side plus original terminal cap segments')
        g.set(g.math('ADD',ny,2.),line.inputs['Count'])
        first=g.compare(index,0);final=g.compare(index,g.math('ADD',ny,1.))
        at=g.math('MAXIMUM',0.,g.math('MINIMUM',last,g.math('SUBTRACT',index,1.)))
        point=g.switch(first,sample(side,at),other_start,'VECTOR')
        point=g.switch(final,point,other_end,'VECTOR')
        graph=bridge._position(g,line.outputs['Mesh'],point)
        delete=g.node('GeometryNodeDeleteGeometry','Omit unused terminal cap endpoints');delete.domain='POINT'
        g.set(graph,delete.inputs['Geometry'])
        g.set(g.either(g.all(first,g.boolean('NOT',prepend)),g.all(final,g.boolean('NOT',append))),delete.inputs['Selection'])
        graph,_count,lo,hi,valid,query=bridge._wire(g,delete.outputs['Geometry'],axis,side)
        ordered.append(graph);queries.append(query);checks.append(valid)
        edge=g.node('GeometryNodeInputMeshEdgeVertices','Slope bound of every original graph segment')
        delta=g.vector('SUBTRACT',edge.outputs['Position 2'],edge.outputs['Position 1'])
        slope=g.math('DIVIDE',g.math('ABSOLUTE',g.vector('DOT_PRODUCT',delta,normal)),
            g.math('MAXIMUM',1e-12,g.math('ABSOLUTE',g.vector('DOT_PRODUCT',delta,axis))))
        slopes.append(g.stat(graph,slope,'EDGE',output='Max'))
        if side==0:low,high=lo,hi
        else:checks.extend((g.close(low,lo,0.),g.close(high,hi,0.)))
    union=bridge._join(g,*ordered)
    station=g.named('_bridge_metric','FLOAT')
    a,b=[query(station) for query in queries]
    gap=g.vector('DOT_PRODUCT',g.vector('SUBTRACT',b,a),normal)
    # A shared cap endpoint has identical coordinates, not merely a near-zero
    # gap. A contact at any interior knot is rejected, including a tangent touch.
    extremum=g.either(g.close(station,low,0.),g.close(station,high,0.))
    shared=g.all(extremum,g.close(g.vector('DISTANCE',a,b),0.,0.))
    # Convert an axial-graph gap into a conservative physical separation. A
    # steep graph can have a large vertical gap but very close physical edges.
    maximum_slope=g.math('MAXIMUM',*slopes)
    margin=g.math('MULTIPLY',4.*tolerance,g.math('SQRT',g.math('ADD',1.,g.math('MULTIPLY',maximum_slope,maximum_slope))))
    positive=g.stat(union,g.either(shared,g.compare(gap,margin,'GREATER_THAN')))
    negative=g.stat(union,g.either(shared,g.compare(gap,g.math('MULTIPLY',-1.,margin),'LESS_THAN')))
    checks.extend((g.compare(g.vector('LENGTH',axis),.99,'GREATER_THAN'),
        g.compare(ny,2.,'GREATER_EQUAL'),g.compare(nx,2.,'GREATER_EQUAL'),
        g.either(positive,negative),
        g.compare(g.stat(union,g.math('ABSOLUTE',gap),output='Max'),margin,'GREATER_THAN')))
    return g.all(*checks)
